import{_ as a,a as t}from"./chunks/autorisations-accessibilite.CsvYiZQ4.js";import{_ as s,o as i,c as o,a2 as n}from"./chunks/framework.D9E58p8B.js";const b=JSON.parse('{"title":"Autorisations","description":"","frontmatter":{"title":"Autorisations"},"headers":[],"relativePath":"guide/autorisations.md","filePath":"guide/autorisations.md"}'),r={name:"guide/autorisations.md"};function l(c,e,d,u,p,m){return i(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="autorisations" tabindex="-1">Autorisations <a class="header-anchor" href="#autorisations" aria-label="Permalink to &quot;Autorisations&quot;">​</a></h1><h2 id="macos" tabindex="-1">macOS <a class="header-anchor" href="#macos" aria-label="Permalink to &quot;macOS&quot;">​</a></h2><p>Daimon a besoin de deux autorisations, toutes deux dans <strong>Réglages Système › Confidentialité et sécurité</strong> :</p><table tabindex="0"><thead><tr><th>Autorisation</th><th>Sert à</th><th>Organes concernés</th></tr></thead><tbody><tr><td><strong>Enregistrement de l&#39;écran</strong></td><td>Voir l&#39;écran</td><td>Vue</td></tr><tr><td><strong>Accessibilité</strong></td><td>Lire la structure des fenêtres et agir</td><td>Touché et Mains</td></tr></tbody></table><p>Le parcours d&#39;installation (panneau › <strong>Relancer l&#39;installation…</strong>) vous guide dans ces deux autorisations.</p><p>Dans chaque volet, le commutateur de la ligne <strong>Daimon</strong> doit être activé :</p><p><img src="'+a+'" alt="Réglages Système, volet Enregistrement de l&#39;écran et des sons du système : la ligne Daimon est activée"></p><p><img src="'+t+'" alt="Réglages Système, volet Accessibilité : la ligne Daimon est activée"></p><p>Ces captures sont recadrées sur la ligne Daimon : vos volets listent aussi les autres applications que vous avez autorisées.</p><h3 id="le-processus-responsable" tabindex="-1">Le processus responsable <a class="header-anchor" href="#le-processus-responsable" aria-label="Permalink to &quot;Le processus responsable&quot;">​</a></h3><p>macOS rattache ces autorisations à l&#39;application qui <em>lance</em> Daimon : c&#39;est votre client IA (son application de bureau, votre terminal, votre éditeur). C&#39;est donc à cette application qu&#39;il faut les accorder, pas à Daimon lui-même.</p><p>Si un outil échoue, demandez à votre IA d&#39;appeler <a href="/Daimon/reference/diagnostic.html#daimon-doctor"><code>daimon_doctor</code></a> : il nomme l&#39;application responsable (clé <code>responsible_app</code>) et dit, pour chaque autorisation, si elle est accordée.</p><h3 id="sans-accessibilite" tabindex="-1">Sans Accessibilité <a class="header-anchor" href="#sans-accessibilite" aria-label="Permalink to &quot;Sans Accessibilité&quot;">​</a></h3><p>Sans l&#39;autorisation Accessibilité, certains outils des Mains ne signalent aucune erreur et n&#39;ont aucun effet. Voir le <a href="./depannage.html">dépannage</a>.</p><h2 id="windows" tabindex="-1">Windows <a class="header-anchor" href="#windows" aria-label="Permalink to &quot;Windows&quot;">​</a></h2><p>Aucune autorisation système n&#39;est à accorder (README public).</p><h2 id="suite" tabindex="-1">Suite <a class="header-anchor" href="#suite" aria-label="Permalink to &quot;Suite&quot;">​</a></h2><p><a href="./modele-mental.html">Modèle mental</a> ou <a href="./depannage.html">dépannage</a>.</p>',18)])])}const _=s(r,[["render",l]]);export{b as __pageData,_ as default};
